//
// GlyphListTable is the compiled form of the Adobe Glyph List and of the ITC
// Zapf Dingbats glyph list (https://github.com/adobe-type-tools/agl-aglfn,
// BSD-3-Clause, read): each glyph name with the Unicode text it stands for,
// sorted by the name's bytes so a lookup is a binary search. The arrays are
// generated by build/fonts/glyph_list.py from third_party/agl/, and each
// table's digest is recorded beside it so a hand edit is found.

#ifndef PDFKIT_FONTS_GENERATED_GLYPH_LIST_TABLE_HPP
#define PDFKIT_FONTS_GENERATED_GLYPH_LIST_TABLE_HPP

#include <span>
#include <string_view>

namespace pdfkit::fonts::generated {

class GlyphListTable {
 public:
  struct Entry {
    std::string_view name;
    // One to four code points.
    std::u32string_view text;
  };

  // The 4,281 names of the Adobe Glyph List, sorted by name.
  [[nodiscard]] static std::span<const Entry> adobe_glyph_list() noexcept;
  // The 201 names of the ITC Zapf Dingbats glyph list (a1 to a191 and the
  // like), sorted by name.
  [[nodiscard]] static std::span<const Entry> zapf_dingbats() noexcept;

  // The SHA-256 the generator computed over each table's canonical lines,
  // "name;HHHH HHHH" with a line feed, in table order.
  [[nodiscard]] static std::string_view adobe_glyph_list_sha256() noexcept;
  [[nodiscard]] static std::string_view zapf_dingbats_sha256() noexcept;
};

}  // namespace pdfkit::fonts::generated

#endif  // PDFKIT_FONTS_GENERATED_GLYPH_LIST_TABLE_HPP
